/**
 *  The Distinct function defined in fun.fbs is for use in cases like:
 *  SELECT COUNT(DISTINCT c0), SUM(c1) FROM t GROUP BY c2;
 *  The `distinct` field here on the query element is to be used to remove duplicate rows, like:
 *  SELECT DISTINCT * FROM t;
 *  or
 *  SELECT DISTINCT ON (c0, c1) FROM t;
 */
export class Distinct {
/**
 *  If `on` is unset or has length 0, then the distinct is:
 *  SELECT DISTINCT * FROM t;
 *  If `on` has length > 0, then distinct is:
 *  SELECT DISTINCT ON (c0, c1) FROM t;
 */
  private _on!: Expr[] | null;

  constructor(arg?: FbsDistinct | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsDistinct.getSizePrefixedRootAsDistinct(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsDistinct) {
      this._initFromFbs(arg);
    } else {
      this._on = null;
    }
  }

  private _initFromFbs(fbs: FbsDistinct): void {
    if (fbs.onLength() > 0) {
      this._on = Array.from({ length: fbs.onLength() }, (_, i) => {
        const item = fbs.on(i);
        return item ? new Expr(item) : new Expr();
      });
    } else {
      this._on = null;
    }
  }

  get on(): Expr[] | null {
    return this._on;
  }

  set on(value: Expr[] | null) {
    this._on = value;
  }

  toFbsT(): FbsDistinctT {
    const t = new FbsDistinctT();
    t.on = this._on ? this._on.map(item => item.toFbsT()) : [];
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}

