export class Query {
  private _boundSources!: TableSourceInstance[] | null;

  private _explain!: Explain | null;

  private _limit!: number;

  private _query!: QueryElement;

  private _values!: ValueInstance[] | null;

  constructor(arg?: FbsQuery | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsQuery.getSizePrefixedRootAsQuery(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsQuery) {
      this._initFromFbs(arg);
    } else {
      this._boundSources = null;
      this._explain = null;
      this._limit = 0;
      this._query = new QueryElement();
      this._values = null;
    }
  }

  private _initFromFbs(fbs: FbsQuery): void {
    if (fbs.boundSourcesLength() > 0) {
      this._boundSources = Array.from({ length: fbs.boundSourcesLength() }, (_, i) => {
        const item = fbs.boundSources(i);
        return item ? new TableSourceInstance(item) : new TableSourceInstance();
      });
    } else {
      this._boundSources = null;
    }
    const explainVal = fbs.explain();
    this._explain = explainVal ? new Explain(explainVal) : null;
    this._limit = fbs.limit();
    const queryVal = fbs.query();
    this._query = queryVal ? new QueryElement(queryVal) : new QueryElement();
    if (fbs.valuesLength() > 0) {
      this._values = Array.from({ length: fbs.valuesLength() }, (_, i) => {
        const item = fbs.values(i);
        return item ? new ValueInstance(item) : new ValueInstance();
      });
    } else {
      this._values = null;
    }
  }

  get boundSources(): TableSourceInstance[] | null {
    return this._boundSources;
  }

  set boundSources(value: TableSourceInstance[] | null) {
    this._boundSources = value;
  }

  get explain(): Explain | null {
    return this._explain;
  }

  set explain(value: Explain | null) {
    this._explain = value;
  }

  get limit(): number {
    return this._limit;
  }

  set limit(value: number) {
    this._limit = value;
  }

  get query(): QueryElement {
    return this._query;
  }

  set query(value: QueryElement) {
    this._query = value;
  }

  get values(): ValueInstance[] | null {
    return this._values;
  }

  set values(value: ValueInstance[] | null) {
    this._values = value;
  }

  toFbsT(): FbsQueryT {
    const t = new FbsQueryT();
    t.boundSources = this._boundSources ? this._boundSources.map(item => item.toFbsT()) : [];
    t.explain = this._explain ? this._explain.toFbsT() : null;
    t.limit = this._limit;
    t.query = this._query.toFbsT();
    t.values = this._values ? this._values.map(item => item.toFbsT()) : [];
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}

